// Runs in the page only; the game worker sends one result over BroadcastChannel.
// This UI is only present at a localhost benchmark URL generated by tools/race_benchmark.py.
if (typeof document !== 'undefined') {
  (() => {
    const query = new URLSearchParams(location.search);
    if (!query.has('benchmark')) return;
    const run = query.get('benchmark'), player = query.get('bench_player');
    if (!/^[a-f0-9-]{36}$/.test(run || '') || !/^[a-z0-9_-]{1,24}$/.test(player || '')) {
      throw new Error('Invalid benchmark session');
    }
    const warmup = Number(query.get('bench_warmup') || 300);
    const steps = Number(query.get('bench_steps') || 1800);
    if (!Number.isInteger(warmup) || warmup < 0 || warmup > 3600 ||
        !Number.isInteger(steps) || steps < 60 || steps > 12000) throw new Error('Invalid benchmark duration');
    const inputRecipe = query.get('bench_input') || 'manual-v1';
    if (!['manual-v1', 'autodrive-v1', 'ghost-v1'].includes(inputRecipe)) throw new Error('Invalid benchmark input recipe');
    const workloadMode = query.get('bench_mode') || 'multiplayer';
    if (!['multiplayer', 'ghost'].includes(workloadMode)) throw new Error('Invalid benchmark mode');
    const config = {run_id: run, player_id: player, warmup_steps: warmup, measure_steps: steps,
                    input_recipe: inputRecipe, workload_mode: workloadMode,
                    expected_players: Number(query.get('bench_clients') || 2),
                    expected_course_id: Number(query.get('bench_course_id') || 0)};
    const channel = new BroadcastChannel('mkw-benchmark-' + run + '-' + player);
    let started = null, ended = null, saved = false, saving = false, settings = null;
    const events = [], roster = [];
    const epochNow = () => performance.timeOrigin + performance.now();
    const environment = () => ({
      user_agent: navigator.userAgent, hardware_concurrency: navigator.hardwareConcurrency,
      device_pixel_ratio: devicePixelRatio, viewport: [innerWidth, innerHeight],
      canvas: [document.getElementById('canvas')?.width, document.getElementById('canvas')?.height],
      visibility: document.visibilityState,
      url_options: Object.fromEntries([...query].filter(([key]) =>
        ['burn', 'log', 'netlog', 'pacetrace', 'nocatchup', 'lagwait', 'oldyield', 'muted'].includes(key))),
    });
    let initialEnvironment = null;
    let barrierTimer = null;
    let status, statusText;
    function show(text) {
      if (!status) {
        status = document.createElement('section');
        status.id = 'benchmark-status';
        status.setAttribute('aria-live', 'polite');
        Object.assign(status.style, {position: 'fixed', bottom: '8px', left: '8px', zIndex: 5,
          background: '#111e', color: '#fff', padding: '10px', maxWidth: '460px', font: '13px system-ui'});
        document.body.append(status);
        statusText = document.createElement('div');
        status.append(statusText);
        if (inputRecipe === 'ghost-v1') {
          const controls = document.createElement('div');
          for (const [label, buttons, steer] of [['Confirm', 0x100, 0], ['Back', 0x200, 0],
                ['Up', 8, 0], ['Down', 4, 0], ['Left', 0, -127], ['Right', 0, 127]]) {
            const button = document.createElement('button');
            button.textContent = label;
            button.onclick = () => channel.postMessage({type: 'menu-input', buttons, steer});
            controls.append(button);
          }
          status.append(controls);
        }
      }
      statusText.textContent = text;
    }
    window.mkwBenchmarkConfig = config;
    window.mkwBenchmarkRoster = (players) => {
      if (started !== null && ended === null) roster.push({at_ms: epochNow(), players: players.map(p => ({id: p.id, inGame: !!p.inGame}))});
      window.mkwBenchmarkLatestRoster = players.map(p => ({id: p.id, inGame: !!p.inGame}));
    };
    for (const type of ['visibilitychange', 'resize', 'keydown', 'pointerdown']) {
      const target = type === 'visibilitychange' ? document : window;
      target.addEventListener(type, (event) => {
        if (started !== null && ended === null && events.length < 10000) {
          events.push({type, at_ms: epochNow(), visibility: document.visibilityState,
                       key: type === 'keydown' ? event.code : undefined});
        }
      }, {passive: true});
    }
    channel.onmessage = async (event) => {
      const message = event.data;
      if (message.type === 'ready') {
        settings = message.settings;
        show(workloadMode === 'ghost' ? 'Benchmark ready: select the saved ghost and Watch Replay. The ghost supplies the driving.'
          : 'Benchmark ready: enter the agreed online race in both clients. Recording starts after warmup.');
      } else if (message.type === 'started') {
        started = message.at_ms;
        initialEnvironment = environment();
        roster.push({at_ms: started, players: window.mkwBenchmarkLatestRoster || []});
        show('Recording ' + workloadMode + ' frame times. Keep the game windows visible.');
      } else if (message.type === 'progress') {
        show('Benchmark ' + message.phase + ': ' + message.steps + ' race steps');
      } else if (message.type === 'finished') {
        ended = message.ended_at_ms;
        show('Capture finished; waiting for the peer before exporting results.');
        try {
          const response = await fetch('/benchmark/finished', {method: 'POST',
            headers: {'Content-Type': 'application/json'}, body: JSON.stringify({run_id: run, player_id: player})});
          if (!response.ok) throw new Error(await response.text());
          const check = async () => {
            const state = await fetch('/benchmark/state?run=' + encodeURIComponent(run), {cache: 'no-store'});
            const data = await state.json();
            if (data.all_finished) {
              clearInterval(barrierTimer);
              channel.postMessage({type: 'publish'});
            }
          };
          await check();
          if (!barrierTimer) barrierTimer = setInterval(() => check().catch(() => {}), 1000);
        } catch (error) {
          show('Could not coordinate the benchmark: ' + error.message + '. This run is incomplete.');
        }
      } else if (message.type === 'result' && !saved && !saving) {
        saving = true;
        clearInterval(barrierTimer);
        ended = message.report.ended_at_ms;
        const report = {...message.report, environment: initialEnvironment || environment(),
                        end_environment: environment(), events, roster};
        try {
          const response = await fetch('/benchmark/result', {method: 'POST',
            headers: {'Content-Type': 'application/json'}, body: JSON.stringify(report)});
          if (!response.ok) throw new Error(await response.text());
          const analysis = await response.json();
          saved = true;
          show(analysis.valid ? 'Benchmark saved for ' + player + '. Finish the replay/race and record its validation.'
            : 'Invalid capture saved: ' + analysis.invalid_reasons.join('; ') + '. Use a new run to measure the intended workload.');
          if (inputRecipe === 'autodrive-v1') {
            const stop = document.createElement('button');
            stop.textContent = 'Stop scripted input';
            stop.onclick = () => { channel.postMessage({type: 'stop-input'}); stop.disabled = true; };
            status.append(stop);
          }
        } catch (error) {
          show('Could not save benchmark: ' + error.message + '. Reloading loses this run.');
          // Keep a local recovery download without requiring a second measurement.
          const button = document.createElement('button');
          button.textContent = 'Download captured result';
          button.onclick = () => {
            const link = document.createElement('a');
            const url = URL.createObjectURL(new Blob([JSON.stringify(report)], {type: 'application/json'}));
            link.href = url; link.download = 'benchmark-' + player + '.json'; link.click();
            URL.revokeObjectURL(url);
          };
          status.append(button);
        } finally { saving = false; }
      }
    };
    addEventListener('DOMContentLoaded', () => show('Benchmark waiting for the game. Use the same course, racers and route for every run.'));
    addEventListener('pagehide', () => channel.postMessage({type: 'cancel', reason: 'page closed before capture completed'}));
  })();
}
